INSERT INTO feature VALUES('let-statements','syntax','Values named in a block (let)',NULL,'implemented','ordinary',NULL,'`let x = v;` returns `v` once and binds it over the rest of its block, and the checker reads the binder as `v`: a type reading `x` sees `v`, and `v` is checked where it is written, read or not; a call it names runs once when it returns and is suspended as a thunk otherwise, so `let g = plus(1)` names a function, and a block, a match, a loop or another form that only runs binds what it returns; a stated type `let x : A = c;` binds at that type, and a pattern splits the value it returns. `let` is the one binding statement: the retired `run x <- c` and `hold x = e` spellings are `let x = c` and `var x = e`.','surface-grammar surface-parser surface-lowering core-checker','corpus/ledger/syntax/block.gandr crates/surface-lowering/src/lower.rs::a_let_binds_a_value_once_and_a_computation_nested crates/core-checker-base/tests/native_formers.rs::a_returned_value_defines_the_binder_it_binds','corpus/ledger/syntax/block.gandr',NULL);
